WHERE races.year = 2008 AND races.name = 'Australian Grand Prix' AND results.position > 0;

SELECT COUNT(*) 
FROM schools 
WHERE City = 'San Francisco' AND StatusType = 'Closed' AND ClosedDate BETWEEN '1989-01-01' AND '1989-12-31';

